.error-page-container {
  display: flex;
  align-items: center;
  justify-content: center;
  height: calc(100vh - 60px);
  width: 100%;
  transition: transform 0.5s;
}
.error-page-container .error {
  width: 400px;
  padding: 40px;
  text-align: center;
}
.error-page-container .error h1, .error-page-container .error .h1 {
  font-size: 125px;
  padding: 0;
  margin: 0;
  font-weight: 700;
}
.error-page-container .error h2, .error-page-container .error .h2 {
  margin: -30px 0 0 0;
  padding: 0;
  font-size: 47px;
  letter-spacing: 12px;
}
.error-page-container .stack-container {
  position: relative;
  width: 420px;
  height: 210px;
  transition: width 1s, height 1s;
}
.error-page-container .stack-container .browser-simulator-container .explode {
  -webkit-animation: explode 0.5s ease-in-out forwards;
  animation: explode 0.5s ease-in-out forwards;
}
.error-page-container .stack-container .browser-simulator-container .perspective {
  perspective: 1000px;
}
.error-page-container .stack-container .browser-simulator-container .perspective .browser-simulator {
  position: absolute;
  -webkit-animation: tilt 0.5s ease-in-out 1s forwards;
  animation: tilt 0.5s ease-in-out 1s forwards;
}
.error-page-container .stack-container .browser-simulator-container .perspective .browser-simulator .page {
  position: relative;
  width: 320px;
  height: 200px;
  background-color: #3F3F3F;
  border: 1px solid #BBBBBB;
  border-radius: 6px 6px 4px 4px;
}
.error-page-container .stack-container .browser-simulator-container .perspective .browser-simulator .page .browser-navigation {
  position: absolute;
  width: 100%;
  height: 12px;
  background-color: #F1F1F1;
  border-top-left-radius: 5px;
  border-top-right-radius: 5px;
}
.error-page-container .stack-container .browser-simulator-container .perspective .browser-simulator .page .browser-navigation .red, .error-page-container .stack-container .browser-simulator-container .perspective .browser-simulator .page .browser-navigation .yellow, .error-page-container .stack-container .browser-simulator-container .perspective .browser-simulator .page .browser-navigation .green {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  margin: 3px;
  float: left;
}
.error-page-container .stack-container .browser-simulator-container .perspective .browser-simulator .page .browser-navigation .red {
  background-color: red;
}
.error-page-container .stack-container .browser-simulator-container .perspective .browser-simulator .page .browser-navigation .yellow {
  background-color: #E6C015;
}
.error-page-container .stack-container .browser-simulator-container .perspective .browser-simulator .page .browser-navigation .green {
  background-color: #60D060;
}
.error-page-container .stack-container .browser-simulator-container .perspective .browser-simulator .page-content {
  padding: 15px;
}
.error-page-container .stack-container .browser-simulator-container .perspective .browser-simulator .page-content ul {
  list-style: none;
  margin: 0;
  padding: 0;
}
.error-page-container .stack-container .browser-simulator-container .perspective .browser-simulator .page-content ul .write-line {
  -webkit-animation: writeLine 0.4s linear forwards;
  animation: writeLine 0.4s linear forwards;
}
.error-page-container .stack-container .browser-simulator-container .perspective .browser-simulator .page-content ul li {
  background-color: #9E9E9E;
  width: 0;
  height: 7px;
  border-radius: 6px;
  margin: 10px 0;
}
.error-page-container .stack-container .poke-up {
  transition: all 0.3s ease;
}
.error-page-container .stack-container .poke-up:hover {
  transform: translateY(-10px);
  transition: 0.3s ease;
}

@-webkit-keyframes tilt {
  0% {
    transform: rotateY(0deg);
  }
  100% {
    transform: rotateY(-30deg);
  }
}
@keyframes tilt {
  0% {
    transform: rotateY(0deg);
  }
  100% {
    transform: rotateY(-30deg);
  }
}
@-webkit-keyframes explode {
  0% {
    transform: translate(0, 0) scale(1);
  }
  100% {
    transform: translate(var(--spreaddist), var(--vertdist)) scale(var(--scaledist));
  }
}
@keyframes explode {
  0% {
    transform: translate(0, 0) scale(1);
  }
  100% {
    transform: translate(var(--spreaddist), var(--vertdist)) scale(var(--scaledist));
  }
}
@-webkit-keyframes writeLine {
  0% {
    width: 0;
  }
  100% {
    width: var(--line-length);
  }
}
@keyframes writeLine {
  0% {
    width: 0;
  }
  100% {
    width: var(--line-length);
  }
}
